(3122368, 436544, 30861, '<td valign="top">Absolutely beautiful rendering here, superb colors &amp; clarity. Whether the voters as a group will see this as a "sky" shot (as opposed to a "boat &amp; water" shot, is an open question. Of course the challenge says make sky a "key element", and it is that, but I am half-expecting voters to mark down images where the sky is not the main "subject". Good luck to you!</td>', 'Absolutely beautiful rendering here, superb colors & clarity. Whether the voters as a group will see this as a "sky" shot (as opposed to a "boat & water" shot, is an open question. Of course the challenge says make sky a "key element", and it is that, but I am half-expecting voters to mark down images where the sky is not the main "subject". Good luck to you!', '2006-12-15 21:35:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3122369, 438670, 30861, '<td valign="top">This is very beautiful. I wish the tree separated from the sky a little better at the top, is my main quibble with it. Everything up there, even the clouds, looks a tad muddy to me. But I like this very much. Good luck with it!</td>', 'This is very beautiful. I wish the tree separated from the sky a little better at the top, is my main quibble with it. Everything up there, even the clouds, looks a tad muddy to me. But I like this very much. Good luck with it!', '2006-12-15 21:35:43.000000', NULL, 1),
(3122375, 438024, 30861, '<td valign="top">This is very powerful, but for me it is marred by the extreme haloing. Great composition, great light on the bldgs.</td>', 'This is very powerful, but for me it is marred by the extreme haloing. Great composition, great light on the bldgs.', '2006-12-15 21:36:55.000000', NULL, 1),
(3122376, 438545, 30861, '<td valign="top">This is nice work with this process. I love the image. Whether the voters will accept it... who knows?</td>', 'This is nice work with this process. I love the image. Whether the voters will accept it... who knows?', '2006-12-15 21:37:00.000000', NULL, 1),
(3122377, 438824, 30861, '<td valign="top">Man, that''s extreme :-) For me the image suffers greatly by being too tight on the bottom. Personally, I think if the moon were a thjrid smaller that would work better also. It''s very nicely done.<br/> <br/>As a nit-picking note, the "Harvest Moon" is defined as the full moon occurring closest to the autumnal equinox, so this isn''t one...</td>', 'Man, that''s extreme :-) For me the image suffers greatly by being too tight on the bottom. Personally, I think if the moon were a thjrid smaller that would work better also. It''s very nicely done. As a nit-picking note, the "Harvest Moon" is defined as the full moon occurring closest to the autumnal equinox, so this isn''t one...', '2006-12-15 21:37:05.000000', NULL, 1),
(3122378, 438798, 30861, '<td valign="top">This is outstanding. I think for me it would work better if the red on the road weren''t so bright, flat, blocked up. But a lovely job.</td>', 'This is outstanding. I think for me it would work better if the red on the road weren''t so bright, flat, blocked up. But a lovely job.', '2006-12-15 21:37:14.000000', NULL, 1),
