(3124054, 438552, 41337, '<td valign="top">Beautiful image. If this is made of several images it''s even more impressive given it''s realism. Good luck.</td>', 'Beautiful image. If this is made of several images it''s even more impressive given it''s realism. Good luck.', '2006-12-16 18:49:11.000000', NULL, 1),
(3124056, 438531, 41337, '<td valign="top">Nice strong focus on the sky and it doesn''t have that missing subject feel to it. Good job.</td>', 'Nice strong focus on the sky and it doesn''t have that missing subject feel to it. Good job.', '2006-12-16 18:50:24.000000', NULL, 1),
(3124060, 437843, 41337, '<td valign="top">This would probably have a great impact if the little branches were clearer. A tighter crop would have helped that.</td>', 'This would probably have a great impact if the little branches were clearer. A tighter crop would have helped that.', '2006-12-16 18:52:30.000000', NULL, 1),
(3124065, 437376, 41337, '<td valign="top">Not a fan of the editing here but the composition is fantastic.</td>', 'Not a fan of the editing here but the composition is fantastic.', '2006-12-16 18:54:35.000000', NULL, 1),
