(3125203, 437408, 24920, '<td valign="top">Very nice. I think however that reserving 2/3 of the image to the sky (and avoid cropping the top of the trees) might have worked better.</td>', 'Very nice. I think however that reserving 2/3 of the image to the sky (and avoid cropping the top of the trees) might have worked better.', '2006-12-17 08:57:15.000000', NULL, 1),
(3125581, 438705, 45524, '<td valign="top">This is a nice landscape. But there is something in the clouds and the sky that take away from it. I can see pixelation perhaps from shadow/highlights, or saturation problems otherwise its a nice image. 6</td>', 'This is a nice landscape. But there is something in the clouds and the sky that take away from it. I can see pixelation perhaps from shadow/highlights, or saturation problems otherwise its a nice image. 6', '2006-12-17 12:33:24.000000', NULL, 1),
