(3125655, 437270, 56744, '<td valign="top">wonderful control of color managment. The amounts of blues are perfect for the amounts of orange giving to the sky and the reflection on the water the key for this photo. Nice, simple and a lot of knowledge about photography are shown here. Congrats</td>', 'wonderful control of color managment. The amounts of blues are perfect for the amounts of orange giving to the sky and the reflection on the water the key for this photo. Nice, simple and a lot of knowledge about photography are shown here. Congrats', '2006-12-17 13:01:56.000000', NULL, 1),
(3125715, 438762, 56744, '<td valign="top">This is a good exemple what a free editing challenge can do... There is no more limits to the differents approach to photography. Good job.</td>', 'This is a good exemple what a free editing challenge can do... There is no more limits to the differents approach to photography. Good job.', '2006-12-17 13:35:17.000000', NULL, 1),
