(3131983, 438571, 51538, '<td valign="top">A striking image.  The picket fence is a little bit too perfect.  Otherwise, it would be hard to find fault.  Perhaps an old wooden bucket in her hands rather than a teddy bear ;-) to go with the rustic nature of the image. 9.</td>', 'A striking image.  The picket fence is a little bit too perfect.  Otherwise, it would be hard to find fault.  Perhaps an old wooden bucket in her hands rather than a teddy bear ;-) to go with the rustic nature of the image. 9.', '2006-12-19 16:15:36.000000', NULL, 1),
(3131984, 438545, 51538, '<td valign="top">Lovely idea and nicely executed. 9.</td>', 'Lovely idea and nicely executed. 9.', '2006-12-19 16:15:42.000000', NULL, 1),
(3131985, 438693, 51538, '<td valign="top">I like the simple effective tones in the picture.  It all works well.  Given a shirt and tie, the effect would be different.  Modern clothing just doesn''t have the elegance it used to have in the early parts of the last century. 9.</td>', 'I like the simple effective tones in the picture.  It all works well.  Given a shirt and tie, the effect would be different.  Modern clothing just doesn''t have the elegance it used to have in the early parts of the last century. 9.', '2006-12-19 16:17:13.000000', NULL, 1),
