INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3145026, 436271, 48228, '<td valign="top">Gee, this is so dam clever, and such a lot of work as well here, from you Judi..... <br/>Deserved a much better score and position  .....</td>', 'Gee, this is so dam clever, and such a lot of work as well here, from you Judi..... Deserved a much better score and position  .....', '2006-12-23 17:12:42.000000', NULL, 0),
(3145414, 438768, 16046, '<td valign="top">wicked color, outstanding image, congrats</td>', 'wicked color, outstanding image, congrats', '2006-12-23 21:35:48.000000', NULL, 0),
(3145416, 437270, 16046, '<td valign="top">Great color Bear, nice job, congrats<br/><br/><i>Message edited by author 2006-12-23 21:37:06.</i></td>', 'Great color Bear, nice job, congrats', '2006-12-23 21:36:43.000000', '2006-12-23 21:37:06.000000', 0),
(3145517, 438843, 66597, '<td valign="top">This is an amazing photo. I gave it an 8 and in looking at it further wish I''d scored it even higher. First, it''s an amazing capture. But amazing captures are often difficult to turn into amazing photos. Yet you succeeded brilliantly. The mist, the sun and the birds all come together for a beautiful, almost ethereal combination. This most assuredly does not suck. Congratulations on your score, but mostly on such an outstanding photo for your portfolio.</td>', 'This is an amazing photo. I gave it an 8 and in looking at it further wish I''d scored it even higher. First, it''s an amazing capture. But amazing captures are often difficult to turn into amazing photos. Yet you succeeded brilliantly. The mist, the sun and the birds all come together for a beautiful, almost ethereal combination. This most assuredly does not suck. Congratulations on your score, but mostly on such an outstanding photo for your portfolio.', '2006-12-23 22:42:36.000000', NULL, 0),
(3145549, 437120, 66597, '<td valign="top">Hi Julianne,<br/>I like the effect with the red birds and I thought overall it was an interesting entry. However, the fuzziness (seems not quite in focus) was a major distractant for me. I also had trouble identifying a focal point - which isn''t always essential - but in this particular shot seemed somehow lacking. Do you have any outtakes? Would be interesting to see.<br/>Best,<br/>Noraneko</td>', 'Hi Julianne,I like the effect with the red birds and I thought overall it was an interesting entry. However, the fuzziness (seems not quite in focus) was a major distractant for me. I also had trouble identifying a focal point - which isn''t always essential - but in this particular shot seemed somehow lacking. Do you have any outtakes? Would be interesting to see.Best,Noraneko', '2006-12-23 23:03:16.000000', NULL, 0),
(3145557, 438824, 66597, '<td valign="top">Jeff,<br/>I wondered if this one was yours while voting. I gave it an 8 due to very strong composition, technically difficult, and beautiful stars on streetlights. The problem I have is that the moon neither looks quite real nor obviously fake. I know this may sound nitpicky, but the orange also seems to clash a little bit with the red "eyes" atop the Washington monument. Just my .02. Overall, a very well done post-process on a difficult shot.</td>', 'Jeff,I wondered if this one was yours while voting. I gave it an 8 due to very strong composition, technically difficult, and beautiful stars on streetlights. The problem I have is that the moon neither looks quite real nor obviously fake. I know this may sound nitpicky, but the orange also seems to clash a little bit with the red "eyes" atop the Washington monument. Just my .02. Overall, a very well done post-process on a difficult shot.', '2006-12-23 23:08:17.000000', NULL, 0),
(3145787, 438843, 32997, '<td valign="top">I hope this is ok...I just kinda wanted to say "wow"...of course that would be a thoughtless comment so I am writing my inner dialogue...hmmm I''m hungry...<br/>no really "wow"...and "cool"...</td>', 'I hope this is ok...I just kinda wanted to say "wow"...of course that would be a thoughtless comment so I am writing my inner dialogue...hmmm I''m hungry...no really "wow"...and "cool"...', '2006-12-24 01:45:39.000000', NULL, 0),
(3145859, 438703, 25952, '<td valign="top">this is a great exposure and has nice colors, but the composition to me looks pretty unsettling, like you just used the fisheye on the tripod to suck as much of the scene into the lens as possible, without much thought on the placement. I really can''t tell what it''s about.</td>', 'this is a great exposure and has nice colors, but the composition to me looks pretty unsettling, like you just used the fisheye on the tripod to suck as much of the scene into the lens as possible, without much thought on the placement. I really can''t tell what it''s about.', '2006-12-24 03:51:12.000000', NULL, 0),
(3145862, 437270, 25952, '<td valign="top">Not sure if i''m stoked about the HDR (mostly the lighter tones in the cattails looks a bit off to me)...but nonetheless great landscape. You know how to catch em perfectly. I like it a lot. Wish I could get somethin like this.</td>', 'Not sure if i''m stoked about the HDR (mostly the lighter tones in the cattails looks a bit off to me)...but nonetheless great landscape. You know how to catch em perfectly. I like it a lot. Wish I could get somethin like this.', '2006-12-24 03:52:32.000000', NULL, 0),
